pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny "dead space" (e.g., 1-5 units) which is hard to fill
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Reward bins that bring the current residual closer to the global mean 
    // to maintain uniformity across bins (Best-Fit principle)
    let mean_alignment = (post_res - mean_residual).abs() * 0.5;

    // Lookahead: If next item is large, favor bins that leave enough room for it
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // progressively more as we reach the end of the stream to force usage of open bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * progress) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Base score is the post_residual (Best-Fit).
    // We combine terms to create a non-linear objective.
    let score = post_res 
        + dead_space_penalty 
        + mean_alignment 
        + lookahead_penalty 
        + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As we approach the end of the stream, we become more conservative about opening new bins.
    if is_new_bin {
        score += 15.0 + (progress * 50.0);
    } else {
        // Reward bins that are "almost full" (Best Fit refinement)
        // Smaller post_residual is better, but we penalize very tight fits that leave 
        // unusable gaps (e.g., residual < 10) if they block better future placements.
        if post_residual < 10 {
            score += 5.0; 
        }

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // prioritize this bin heavily to create a "perfect" packing pair.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    }

    // Global state awareness:
    // If we have many open bins, penalize opening another one.
    // If the mean residual of existing bins is high, we prefer to fill them rather than create new ones.
    if !is_new_bin {
        score += (open_bins_count as f64 * 0.5);
        score += (mean_residual * 0.1);
    }

    // Criticality: If this is the last bin that can fit the item, 
    // we should prioritize it to avoid forced new-bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Dynamic constraint: If the item is large (>= 75), prioritize bins that 
    // have exactly enough space (minimizing fragmentation).
    if item_size >= 75 && post_residual < 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero,
    // as they create "stranded" space that cannot fit common item sizes (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // favor this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Fragmentation Avoidance: If this bin is the only one that can fit the item,
    // penalize opening a new bin by artificially lowering the score of existing bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. New Bin Thresholding: If we are considering a new bin (residual == capacity),
    // only accept it if the item is large or the mean residual of existing bins is 
    // already quite low (suggesting we are packing efficiently).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin unless existing bins are very full
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 5. Modulo-based "Perfect Fit" reward: 
    // If the item size is a divisor of the bin capacity (e.g., 20, 25, 50),
    // prioritize filling the bin to exactly 0 residual.
    if bin_capacity % item_size == 0 && post_residual == 0 {
        score -= 30.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
